	@Test
	void nestedTelemetryRequestUsesItsOwnResourceOwner() {
		try (var outerContext = QueryExplanationContext.enter(Explanation.Level.Telemetry)) {
			var outerCollector = QueryExplanationContext.telemetry();
			var outer = LmdbQueryTelemetry.current();
			try (var active = LmdbQueryTelemetry.enter(outer)) {
				outer.decodeRequest();
				try (var innerContext = QueryExplanationContext.enter(Explanation.Level.Telemetry)) {
					var innerCollector = QueryExplanationContext.telemetry();
					var inner = LmdbQueryTelemetry.current();
					assertThat(inner).isNotSameAs(outer);
					inner.decodeRequest();
					inner.decodeRequest();
					assertThat(metric(innerCollector.snapshot(), "valueDecodeRequests")).isEqualTo(2);
				}
				assertThat(LmdbQueryTelemetry.current()).isSameAs(outer);
				assertThat(metric(outerCollector.snapshot(), "valueDecodeRequests")).isEqualTo(1);
			}
		}
	}

	@Test
	void nestedUnmeasuredRequestSuppressesCapturedOuterOwner() {
		try (var outerContext = QueryExplanationContext.enter(Explanation.Level.Telemetry)) {
			var outer = LmdbQueryTelemetry.current();
			try (var active = LmdbQueryTelemetry.enter(outer)) {
				for (var level : new Explanation.Level[] { Explanation.Level.Timed, Explanation.Level.Executed }) {
					try (var nested = QueryExplanationContext.enter(level)) {
						assertThat(LmdbQueryTelemetry.current()).isNull();
					}
					assertThat(LmdbQueryTelemetry.current()).isSameAs(outer);
				}
			}
		}
	}

