	@Test
	void ownerPeaksAndRefusalsFollowReservationGrowthAndRelease() {
		try (var ignored = QueryExplanationContext.enter(Explanation.Level.Telemetry)) {
			var collector = QueryExplanationContext.telemetry();
			var manager = LmdbQueryMemoryManager.createForTesting(200, 100);
			try (var ledger = manager.openQuery()) {
				var join = ledger.reserve(60, null, "hash-join");
				var group = ledger.reserve(20, null, "count-group-arena");
				assertThat(join.tryGrow(10)).isTrue();
				join.release(40);
				group.close();
				assertThat(ledger.reserve(50, null, "count-group-arena")).isNotNull();
				assertThat(join.tryGrow(40)).isFalse();
				assertThat(group.tryGrow(1)).isFalse();
				assertThat(ownerMetric(collector.snapshot(), "hash-join", "memoryReservedBytes")).isEqualTo(30);
				assertThat(ownerMetric(collector.snapshot(), "count-group-arena", "memoryReservedBytes")).isEqualTo(50);
			}
			var profile = collector.snapshot();
			assertThat(metric(profile, "memoryPeakReservedBytes")).isEqualTo(90);
			assertThat(ownerMetric(profile, "hash-join", "memoryPeakReservedBytes")).isEqualTo(70);
			assertThat(ownerMetric(profile, "count-group-arena", "memoryPeakReservedBytes")).isEqualTo(50);
			assertThat(ownerMetric(profile, "hash-join", "memoryReservedBytes")).isZero();
			assertThat(ownerMetric(profile, "count-group-arena", "memoryReservedBytes")).isZero();
			assertThat(ownerMetric(profile, "hash-join", "memoryQueryLimitRefusals")).isEqualTo(1);
			assertThat(ownerMetric(profile, "hash-join", "memoryGlobalLimitRefusals")).isZero();
			assertThat(ownerMetric(profile, "count-group-arena", "memoryClosedRefusals")).isEqualTo(1);
		}
	}

