	@Test
	void fileCountersMeasureTransferredBytesAndScopesRestore() throws Exception {
		LmdbQueryTelemetry captured;
		try (var ignored = QueryExplanationContext.enter(Explanation.Level.Telemetry)) {
			captured = LmdbQueryTelemetry.current();
		}
		assertThat(LmdbQueryTelemetry.current()).isNull();
		try (var scope = LmdbQueryTelemetry.enter(captured)) {
			ByteArrayOutputStream bytes = new ByteArrayOutputStream();
			try (var output = captured.spillOutput(bytes)) {
				output.write(new byte[41]);
				output.write(1);
			}
			try (var input = captured.spillInput(new ByteArrayInputStream(bytes.toByteArray()))) {
				assertThat(input.readNBytes(5)).hasSize(5);
				assertThat(input.read()).isZero();
			}
			assertThat(metric(captured.collector().snapshot(), "spillFileWriteBytes")).isEqualTo(42);
			assertThat(metric(captured.collector().snapshot(), "spillFileReadBytes")).isEqualTo(6);
			try (var disabled = LmdbQueryTelemetry.enter(null)) {
				assertThat(LmdbQueryTelemetry.current()).isNull();
			}
			assertThat(LmdbQueryTelemetry.current()).isSameAs(captured);
		}
		assertThat(LmdbQueryTelemetry.current()).isNull();
	}

