	private static long metric(QueryExecutionProfile profile, String name) {
		return profile.stages()
				.stream()
				.filter(stage -> stage.metrics().containsKey(name))
				.findFirst()
				.orElseThrow()
				.metrics()
				.get(name)
				.count();
	}

	private static long ownerMetric(QueryExecutionProfile profile, String owner, String name) {
		return profile.stages()
				.stream()
				.filter(stage -> owner.equals(stage.properties().get("reservationOwner")))
				.findFirst()
				.orElseThrow()
				.metrics()
				.get(name)
				.count();
	}
